package com.datalens.chart;
import java.util.*;import java.time.Instant;
import org.junit.jupiter.api.*;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
import org.springframework.security.access.AccessDeniedException;
import com.datalens.semantic.*;import com.datalens.semantic.SemanticModels.*;import com.datalens.identity.CurrentActor;import com.datalens.datasource.SourceModels.Field;import com.datalens.query.QueryModels.Parameter;import static com.datalens.chart.ChartModels.*;
class ChartSemanticAuthorizationTest {
 final SemanticService semantics=mock(SemanticService.class);final ChartSemanticAuthorization guard=new ChartSemanticAuthorization(semantics);final CurrentActor actor=new CurrentActor(1,"a","USER",1);
 Metric metric(){return new Metric("sales","Sales",List.of(),"COUNT(day)","reviewed","day","owner","count","daily","ignore","UTC",List.of("day"),"SELECT COUNT(day) AS sales FROM orders WHERE day >= ? AND day < ?",List.of(new Parameter("DATE","2026-01-01"),new Parameter("DATE","2026-02-01")),new TimeParameters(0,1,"UTC","DATE"));}
 Publication publication(long version,String digest,String sensitivity){return new Publication("subject",version,new Document(List.of(new BusinessField("day","Day",List.of(),new Field("orders","day"),"DATE","day",sensitivity)),List.of(metric()),List.of(),List.of(),List.of()),digest,"scope",1,1,Instant.EPOCH,Instant.EPOCH);}
 Definition definition(TimeRule rule){var m=metric();return new Definition("subject",m.sql(),m.parameters(),rule,ChartSemanticAuthorization.description(m),new Spec("TABLE",null,List.of()),new SemanticBinding(1,"a".repeat(64),"scope","sales"));}
 @BeforeEach void setup(){when(semantics.retrievePublished(actor,"subject")).thenReturn(publication(1,"a".repeat(64),"PUBLIC"));}
 @Test void approvedPreviousMonthAndUnchangedMetricPass(){guard.validate(actor,definition(new TimeRule("NONE",null,null,null,null)));guard.validate(actor,definition(SemanticRules.lastMonthRule(metric())));}
 @Test void republishDigestAndSensitivityChangesDeny(){for(var p:List.of(publication(2,"a".repeat(64),"PUBLIC"),publication(1,"b".repeat(64),"PUBLIC"),publication(1,"a".repeat(64),"SENSITIVE"))){when(semantics.retrievePublished(actor,"subject")).thenReturn(p);assertThatThrownBy(()->guard.validate(actor,definition(SemanticRules.lastMonthRule(metric())))).isInstanceOf(AccessDeniedException.class);}}
 @Test void editedSqlOrParameterCannotRetainReviewedBadge(){var d=definition(SemanticRules.lastMonthRule(metric()));assertThatThrownBy(()->guard.validate(actor,new Definition(d.subjectId(),"SELECT day FROM orders",d.parameters(),d.timeRule(),d.metricDescription(),d.spec(),d.semanticBinding()))).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->guard.validate(actor,new Definition(d.subjectId(),d.sql(),List.of(new Parameter("DATE","2000-01-01")),d.timeRule(),d.metricDescription(),d.spec(),d.semanticBinding()))).isInstanceOf(AccessDeniedException.class);}
 @Test void timezoneAndUnsupportedRelativeRangeCannotOverrideContract(){for(var rule:List.of(new TimeRule("LAST_MONTH",null,"America/New_York",0,1),new TimeRule("LAST_DAYS",30,"UTC",0,1),new TimeRule("LAST_MONTH",null,"UTC",1,0)))assertThatThrownBy(()->guard.validate(actor,definition(rule))).isInstanceOf(AccessDeniedException.class);}
 @Test void manualChartsHaveNoModelOrSemanticDependency(){var d=definition(new TimeRule("NONE",null,null,null,null));guard.validate(actor,new Definition(d.subjectId(),d.sql(),d.parameters(),d.timeRule(),d.metricDescription(),d.spec()));verifyNoInteractions(semantics);}
 @Test void falseBusinessDescriptionCannotRetainSemanticProvenance(){var d=definition(new TimeRule("NONE",null,null,null,null));assertThatThrownBy(()->guard.validate(actor,new Definition(d.subjectId(),d.sql(),d.parameters(),d.timeRule(),"Fabricated business meaning",d.spec(),d.semanticBinding()))).isInstanceOf(AccessDeniedException.class);}
}
